const DAYS: [u32; 13] = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

fn is_leap_year(year: u32) -> bool {
    year.is_multiple_of(4) && (!year.is_multiple_of(100) || year.is_multiple_of(400))
}

fn captures(pattern: &str, value: &str) -> Option<Vec<Option<String>>> {
    let regex = js_regex(pattern)?;
    let found = regex.captures(value).ok()??;
    Some(
        found
            .iter()
            .map(|group| group.map(|group| group.as_str().to_string()))
            .collect(),
    )
}

fn number(group: &Option<String>) -> u32 {
    group
        .as_deref()
        .and_then(|text| text.parse().ok())
        .unwrap_or(0)
}

fn is_date(value: &str) -> bool {
    let Some(groups) = captures(DATE, value) else {
        return false;
    };
    let (year, month, day) = (number(&groups[1]), number(&groups[2]), number(&groups[3]));
    (1..=12).contains(&month)
        && day >= 1
        && day
            <= if month == 2 && is_leap_year(year) {
                29
            } else {
                DAYS[month as usize]
            }
}

fn is_time(value: &str) -> bool {
    let Some(groups) = captures(TIME, value) else {
        return false;
    };
    if groups[4].is_none() && groups[5].is_none() {
        return false;
    }
    let (hour, minute, second) = (number(&groups[1]), number(&groups[2]), number(&groups[3]));
    if hour > 23 || minute > 59 || second > 60 {
        return false;
    }
    if groups[5].is_some() && (number(&groups[6]) > 23 || number(&groups[7]) > 59) {
        return false;
    }
    if second < 60 {
        return true;
    }
    // A leap second is valid only at 23:59:60 UTC.
    let sign: i64 = if groups[5].as_deref() == Some("-") {
        -1
    } else {
        1
    };
    let offset = i64::from(number(&groups[6])) * 60 + i64::from(number(&groups[7]));
    let utc = i64::from(hour) * 60 + i64::from(minute) - sign * offset;
    (utc % 1440 + 1440) % 1440 == 1439
}

fn is_date_time(value: &str) -> bool {
    let parts: Vec<&str> = value.split(['T', 't']).collect();
    parts.len() == 2 && is_date(parts[0]) && is_time(parts[1])
}

/// RFC 1123 host names: dot-separated labels of letters, digits and inner hyphens, at most 63
/// characters each and 253 in all.
fn is_hostname(value: &str) -> bool {
    let name = value.strip_suffix('.').unwrap_or(value);
    !name.is_empty()
        && name.len() <= 253
        && name.split('.').all(|label| {
            !label.is_empty()
                && label.len() <= 63
                && !label.starts_with('-')
                && !label.ends_with('-')
                && label
                    .chars()
                    .all(|character| character.is_ascii_alphanumeric() || character == '-')
        })
}

fn matches(pattern: &str, value: &str) -> bool {
    js_regex(pattern).is_some_and(|regex| regex.is_match(value).unwrap_or(false))
}

/// Whether `value` has the format; a format TypeBox does not register passes.
pub(crate) fn check_format(format: &str, value: &str) -> bool {
    match format {
        "date-time" => is_date_time(value),
        "date" => is_date(value),
        "time" => is_time(value),
        "duration" => matches(DURATION, value),
        "email" | "idn-email" => matches(EMAIL, value),
        "hostname" | "idn-hostname" => is_hostname(value),
        "ipv4" => matches(IPV4, value),
        "ipv6" => matches(IPV6, value),
        "uri" | "iri" => matches(URI, value),
        "uri-reference" | "iri-reference" => matches(URI_REFERENCE, value),
        "uri-template" => matches(URI_TEMPLATE, value),
        "url" => value.split_once("://").is_some_and(|(scheme, rest)| {
            matches("^[a-zA-Z][a-zA-Z0-9+.-]*$", scheme) && !rest.is_empty()
        }),
        "uuid" => matches(UUID, value),
        "json-pointer" => matches(JSON_POINTER, value),
        "json-pointer-uri-fragment" => matches(JSON_POINTER_URI_FRAGMENT, value),
        "relative-json-pointer" => matches(RELATIVE_JSON_POINTER, value),
        "regex" => js_regex(value).is_some(),
        _ => true,
    }
}
